<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\UserGrantedClientScopesUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserGrantedClientScopesUserAccessor
{
    private UserGrantedClientScopesUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserGrantedClientScopesUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserGrantedClientScopesUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserGrantedClientScopesUserVO::from($user);
        return $copy;
    }
}
